
var $=function(i){return document.getElementById(i)};
var q=new URLSearchParams(location.search);
var NOMBRE=q.get('nombre')||'miss Padilla', DE=q.get('de')||'Gabriela', EDAD=parseInt(q.get('edad'),10)||0;
function h(t){var d=document.createElement('div');d.textContent=t;return d.innerHTML;}
var HN=h(NOMBRE),HD=h(DE);
var RED=matchMedia('(prefers-reduced-motion:reduce)').matches;
document.querySelectorAll('.nom').forEach(function(e){e.textContent=NOMBRE;});
$('cvNom').textContent=NOMBRE;$('cvNom').setAttribute('font-size',Math.max(16,Math.min(30,230/Math.max(NOMBRE.length,1)*1.3)));

/* ---------- sonido ---------- */
var AC=null,muted=false;
function ctx(){if(!AC){try{AC=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}}return AC;}
function tono(f,t0,d,tipo,vol){var a=ctx();if(!a||muted)return;var o=a.createOscillator(),g=a.createGain(),t=a.currentTime+t0;
  o.type=tipo||'sine';o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(vol||.15,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+d);
  o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+d+.05);}
function pop(){tono(700,0,.1,'sine',.12);tono(1050,.05,.14,'sine',.09);if(navigator.vibrate)navigator.vibrate(10);}
function chime(){[523,659,784,1047].forEach(function(f,i){tono(f,i*.09,.6,'sine',.11);});}
function cumple(){if(AUD&&!AUD.paused)return;var n=[[392,.3],[392,.2],[440,.55],[392,.55],[523,.55],[494,1]],t=0;n.forEach(function(x){tono(x[0],t,x[1]+.25,'triangle',.15);t+=x[1];});}
$('snd').onclick=function(){muted=!muted;this.classList.toggle('off',muted);this.setAttribute('aria-pressed',muted);this.setAttribute('aria-label',muted?'Activar sonido':'Silenciar sonido');if(AUD)AUD.muted=muted;};

/* ---------- partículas (confeti, destellos, humo) ---------- */
var fx=$('fx'),fc=fx.getContext('2d'),P=[],run=false,COL=['#ffb6d0','#ffd3b8','#fff1b8','#c9f3de','#bfe2ff','#d8c9ff','#ff8fb8'];
function size(){fx.width=innerWidth;fx.height=innerHeight;}size();addEventListener('resize',size);
function add(p){P.push(p);if(!run){run=true;requestAnimationFrame(draw);}}
function estrella(c,r){c.beginPath();for(var i=0;i<4;i++){var a=i*Math.PI/2;c.lineTo(Math.cos(a)*r,Math.sin(a)*r);a+=Math.PI/4;c.lineTo(Math.cos(a)*r*.28,Math.sin(a)*r*.28);}c.closePath();c.fill();}
function draw(){
  fc.clearRect(0,0,fx.width,fx.height);
  P=P.filter(function(p){p.x+=p.vx;p.y+=p.vy;p.vy+=p.g;p.r+=p.vr;p.l--;
    fc.globalAlpha=Math.max(0,p.l/p.m);fc.fillStyle=p.c;fc.save();fc.translate(p.x,p.y);fc.rotate(p.r);
    if(p.t==='s')estrella(fc,p.s);else if(p.t==='o'){fc.beginPath();fc.arc(0,0,p.s,0,6.283);fc.fill();}else fc.fillRect(-p.s/2,-p.s/3,p.s,p.s*.66);
    fc.restore();return p.l>0;});
  fc.globalAlpha=1;
  if(P.length)requestAnimationFrame(draw);else{run=false;fc.clearRect(0,0,fx.width,fx.height);}
}
function boom(x,y,n){
  pop();if(RED)return;x=x==null?innerWidth/2:x;y=y==null?innerHeight*.6:y;n=n||130;
  for(var i=0;i<n;i++)add({x:x,y:y,vx:(Math.random()-.5)*15,vy:-Math.random()*15-3,g:.4,r:Math.random()*6,vr:(Math.random()-.5)*.4,s:Math.random()*8+5,c:COL[i%COL.length],t:i%3===0?'o':i%3===1?'s':'r',l:110,m:110});
}
function humo(x,y){if(RED)return;for(var i=0;i<7;i++)add({x:x,y:y,vx:(Math.random()-.5)*.8,vy:-Math.random()*1.4-.4,g:-.01,r:0,vr:0,s:5+Math.random()*5,c:'#d9d1ea',t:'o',l:60,m:60});}
var lastS=0;
addEventListener('pointermove',function(e){
  var now=Date.now();
  if(!RED&&now-lastS>45&&(e.pointerType==='mouse'||e.buttons)){lastS=now;add({x:e.clientX,y:e.clientY,vx:(Math.random()-.5)*1.2,vy:Math.random()*1.2,g:.03,r:0,vr:.08,s:5+Math.random()*5,c:COL[(Math.random()*COL.length)|0],t:'s',l:36,m:36});}
  var sw=$('sw');sw.style.setProperty('--rx',(e.clientX/innerWidth-.5).toFixed(2));sw.style.setProperty('--ry',(e.clientY/innerHeight-.5).toFixed(2));
});
/* ondas en botones */
document.addEventListener('pointerdown',function(e){var b=e.target.closest('.btn,.ic,.bub,.opts button');if(!b||b.disabled)return;
  var r=b.getBoundingClientRect(),s=document.createElement('span'),d=Math.max(r.width,r.height)*2;s.className='rp';
  s.style.cssText='width:'+d+'px;height:'+d+'px;left:'+(e.clientX-r.left-d/2)+'px;top:'+(e.clientY-r.top-d/2)+'px';b.appendChild(s);setTimeout(function(){s.remove();},700);});

/* ---------- portada ---------- */
var rec=$('rec'),dy=0,drag=false,sy=0,moved=false,opened=false;
rec.addEventListener('pointerdown',function(e){drag=true;moved=false;sy=e.clientY;rec.classList.add('drag');rec.setPointerCapture(e.pointerId);});
rec.addEventListener('pointermove',function(e){if(!drag)return;dy=Math.min(0,Math.max(-190,e.clientY-sy));if(Math.abs(dy)>6)moved=true;rec.style.setProperty('--dy',dy+'px');});
rec.addEventListener('pointerup',function(){if(!drag)return;drag=false;rec.classList.remove('drag');if(dy<-70||!moved)abrirDisco();else{dy=0;rec.style.setProperty('--dy','0px');}});
rec.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();abrirDisco();}});
$('abrir').onclick=abrirDisco;
function abrirDisco(){
  if(opened)return;opened=true;rec.classList.add('out');chime();boom(innerWidth/2,innerHeight*.45,70);
  setTimeout(function(){irA('player');},800);
}
function irA(id){document.querySelectorAll('.scr').forEach(function(s){s.classList.remove('on')});$(id).classList.add('on');}

/* ---------- tocadiscos ---------- */
var vin=$('vin'),arm=$('arm'),playing=false,ang=0,spd=0,vdrag=false,aArm=96,armDrag=false,armMoved=false,primera=true;
(function loop(){
  var tgt=playing?(RED?.3:1.5):0;
  if(!vdrag){spd+=(tgt-spd)*.035;ang+=spd;}
  vin.style.transform='rotate('+ang+'deg)';
  requestAnimationFrame(loop);
})();
function setArm(a,anim){arm.classList.toggle('drag',!anim);arm.style.transform='rotate('+(-a)+'deg)';aArm=a;}
function ponPlay(on){
  if(AUD){if(on)AUD.play().catch(function(){});else AUD.pause();return;}
  playing=on;$('eq').classList.toggle('on',on);setArm(on?44:96,true);
  $('np').textContent=on?'Sonando: tributo a Chayanne':'Ponga la aguja sobre el disco';
  if(on){pop();if(primera){primera=false;cumple();}}
}
function estado(on){
  playing=on;$('eq').classList.toggle('on',on);setArm(on?44:96,true);
  $('np').textContent=on?'Sonando: Dejaría todo':'Ponga la aguja sobre el disco';
  var e2=$('eq2');if(e2)e2.classList.toggle('on',on);
  var m=$('mini');if(m)m.classList.toggle('on',on);
  var mu=$('mu');if(mu){mu.textContent=on?'Pausar música':'Reproducir música';mu.setAttribute('aria-pressed',on);}
}
function enlazar(a){a.loop=true;a.onplay=function(){estado(true)};a.onpause=function(){estado(false)};}
var vA=0,lastT=0;
function aVin(e){var r=vin.getBoundingClientRect();return Math.atan2(e.clientY-(r.top+r.height/2),e.clientX-(r.left+r.width/2))*180/Math.PI;}
vin.addEventListener('pointerdown',function(e){vdrag=true;vA=aVin(e);vin.setPointerCapture(e.pointerId);});
vin.addEventListener('pointermove',function(e){if(!vdrag)return;var a=aVin(e),d=a-vA;if(d>180)d-=360;if(d<-180)d+=360;ang+=d;spd=d*.6;vA=a;
  var n=Date.now();if(Math.abs(d)>5&&n-lastT>70){lastT=n;tono(180+Math.random()*160,0,.05,'sawtooth',.025);}});
vin.addEventListener('pointerup',function(){vdrag=false;});
function pivot(){var p=document.querySelector('.pivot').getBoundingClientRect();return {x:p.left+p.width/2,y:p.top+p.height/2};}
arm.addEventListener('pointerdown',function(e){armDrag=true;armMoved=false;arm.setPointerCapture(e.pointerId);arm.classList.add('drag');});
arm.addEventListener('pointermove',function(e){if(!armDrag)return;var p=pivot(),a=Math.atan2(e.clientY-p.y,-(e.clientX-p.x))*180/Math.PI;a=Math.max(40,Math.min(100,a));armMoved=true;setArm(a,false);});
arm.addEventListener('pointerup',function(){if(!armDrag)return;armDrag=false;arm.classList.remove('drag');
  if(!armMoved)ponPlay(!playing);else ponPlay(aArm<=64);});
arm.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();ponPlay(!playing);}});
setArm(96,true);

